from dataclasses import dataclass

import numpy as np


@dataclass(frozen=True)
class PIDGains:
    kp: np.ndarray
    ki: np.ndarray
    kd: np.ndarray


class PID:
    def __init__(self, gains: PIDGains, integral_limit: float = 1.0):
        self.gains = gains
        self.integral_limit = float(integral_limit)
        self.integral = np.zeros(3, dtype=float)

    def reset(self) -> None:
        self.integral[:] = 0.0

    def update(self, e: np.ndarray, e_dot: np.ndarray, dt: float) -> np.ndarray:
        self.integral += np.array(e, dtype=float).reshape(3) * float(dt)
        self.integral = np.clip(self.integral, -self.integral_limit, self.integral_limit)
        return (
            self.gains.kp * e
            + self.gains.kd * e_dot
            + self.gains.ki * self.integral
        )


class PositionController:
    def __init__(self, gains: PIDGains, integral_limit: float = 2.0):
        self.pid = PID(gains, integral_limit=integral_limit)

    def reset(self) -> None:
        self.pid.reset()

    def accel_command(
        self,
        pos: np.ndarray,
        vel: np.ndarray,
        pos_des: np.ndarray,
        vel_des: np.ndarray,
        acc_ff: np.ndarray,
        dt: float,
    ) -> np.ndarray:
        e_p = pos_des - pos
        e_v = vel_des - vel
        return np.array(acc_ff, dtype=float).reshape(3) + self.pid.update(e_p, e_v, dt)


class AttitudeController:
    def __init__(self, gains: PIDGains, integral_limit: float = 0.5):
        self.pid = PID(gains, integral_limit=integral_limit)

    def reset(self) -> None:
        self.pid.reset()

    def moment_command(
        self,
        euler: np.ndarray,
        omega: np.ndarray,
        euler_des: np.ndarray,
        omega_des: np.ndarray,
        dt: float,
    ) -> np.ndarray:
        e_a = euler_des - euler
        # Wrap yaw error into [-pi, pi] for robustness.
        e_a[2] = (e_a[2] + np.pi) % (2.0 * np.pi) - np.pi
        e_w = omega_des - omega
        return self.pid.update(e_a, e_w, dt)
