import numpy as np


def stepinfo_3d(
    pos_actual: np.ndarray,
    pos_target: np.ndarray,
    t: np.ndarray,
    settling_threshold: float = 0.02,
) -> dict:
    pos_actual = np.array(pos_actual, dtype=float)
    pos_target = np.array(pos_target, dtype=float).reshape(3)
    t = np.array(t, dtype=float).reshape(-1)

    dist = np.linalg.norm(pos_actual.T - pos_target.reshape(1, 3), axis=1)
    d0 = float(dist[0])
    if d0 < 1e-6:
        return {
            "RiseTime": 0.0,
            "SettlingTime": 0.0,
            "Overshoot_pct": 0.0,
            "SteadyStateError": float(dist[-1]),
        }

    rise_band = 0.1 * d0
    settle_band = settling_threshold * d0

    rise_time = 0.0
    for k in range(len(t)):
        if dist[k] <= rise_band:
            rise_time = float(t[k])
            break

    settling_time = float(t[-1])
    for k in range(len(t) - 1, -1, -1):
        if dist[k] > settle_band:
            settling_time = float(t[k])
            break

    entered = np.where(dist <= settle_band)[0]
    if len(entered) == 0:
        overshoot = 0.0
    else:
        k0 = int(entered[0])
        overshoot = float(np.max(dist[k0:]) / d0 * 100.0)

    return {
        "RiseTime": rise_time,
        "SettlingTime": settling_time,
        "Overshoot_pct": overshoot,
        "SteadyStateError": float(dist[-1]),
    }
