import yaml


@dataclass(frozen=True)
class SystemParams:
    sample_rate: float
    mass: float
    gravity: float
    arm_length: float
    motor_spread_angle: float
    thrust_coefficient: float
    moment_scale: float
    motor_constant: float
    rpm_min: float
    rpm_max: float
    inertia_diag: np.ndarray  # shape (3,)
    COM_vertical_offset: float
    accel_limit_up: float
    accel_limit_down: float
    accel_limit_horiz: float

    @property
    def dt(self) -> float:
        return 1.0 / float(self.sample_rate)

    @property
    def inertia(self) -> np.ndarray:
        return np.diag(self.inertia_diag.astype(float))

    @property
    def inv_inertia(self) -> np.ndarray:
        return np.diag(1.0 / self.inertia_diag.astype(float))

    @property
    def prop_matrix(self) -> np.ndarray:
        # X-frame, matches the benchmark skill description.
        d = float(self.arm_length)
        cT = float(self.thrust_coefficient)
        cQ = float(self.moment_scale)
        return np.array(
            [
                [cT, cT, cT, cT],
                [0.0, d * cT, 0.0, -d * cT],
                [-d * cT, 0.0, d * cT, 0.0],
                [-cQ, cQ, -cQ, cQ],
            ],
            dtype=float,
        )

    @property
    def thrust_min(self) -> float:
        return 4.0 * self.thrust_coefficient * (self.rpm_min**2)

    @property
    def thrust_max(self) -> float:
        return 4.0 * self.thrust_coefficient * (self.rpm_max**2)


