{"command": "create", "path": "/root/drone_sim/command_parser.py", "file_text": "from __future__ import annotations

from dataclasses import dataclass
import re

import numpy as np


@dataclass(frozen=True)
class Command:
    mode: str  # takeoff | hover | land | fly
    duration: float
    start_pos: np.ndarray  # (3,)
    end_pos: np.ndarray  # (3,)
    yaw: float = 0.0


_TAKEOFF_RE = re.compile(r"^Take off to\s+([0-9.]+)\s*m height in\s+([0-9.]+)\s*seconds$", re.IGNORECASE)
_HOVER_RE = re.compile(r"^Hover at\s+([0-9.]+)\s*m height for\s+([0-9.]+)\s*seconds$", re.IGNORECASE)
_LAND_RE = re.compile(r"^Land from\s+([0-9.]+)\s*m height in\s+([0-9.]+)\s*seconds$", re.IGNORECASE)
_FLY_RE = re.compile(
    r"^Fly from\s*\(([^)]+)\)\s*to\s*\(([^)]+)\)\s*in\s*([0-9.]+)\s*seconds$",
    re.IGNORECASE,
)


def _parse_xyz(triple: str) -> np.ndarray:
    parts = [p.strip() for p in triple.split(",")]
    if len(parts) != 3:
        raise ValueError(f"Expected 3 comma-separated values, got: {triple!r}")
    return np.array([float(parts[0]), float(parts[1]), float(parts[2])], dtype=float)


def parse_command_text(text: str) -> Command:
    txt = text.strip()

    m = _TAKEOFF_RE.match(txt)
    if m:
        h = float(m.group(1))
        T = float(m.group(2))
        return Command(
            mode="takeoff",
            duration=T,
            start_pos=np.array([0.0, 0.0, 0.0], dtype=float),
            end_pos=np.array([0.0, 0.0, h], dtype=float),
        )

    m = _HOVER_RE.match(txt)
    if m:
        h = float(m.group(1))
        T = float(m.group(2))
        p = np.array([0.0, 0.0, h], dtype=float)
        return Command(mode="hover", duration=T, start_pos=p, end_pos=p.copy())

    m = _LAND_RE.match(txt)
    if m:
        h = float(m.group(1))
        T = float(m.group(2))
        return Command(
            mode="land",
            duration=T,
            start_pos=np.array([0.0, 0.0, h], dtype=float),
            end_pos=np.array([0.0, 0.0, 0.0], dtype=float),
        )

    m = _FLY_RE.match(txt)
    if m:
        p0 = _parse_xyz(m.group(1))
        p1 = _parse_xyz(m.group(2))
        T = float(m.group(3))
        return Command(mode="fly", duration=T, start_pos=p0, end_pos=p1)

    raise ValueError(f"Unsupported command: {txt!r}")
", "security_risk": "MEDIUM", "summary": "Create natural language command parser"}

